const ids = ['cafef-chungkhoan','cafef-doanhnghiep','vietstock-cophieu','vietstock-giaodichnoibo','vietstock-en-stocks'];
const urls = {
 'cafef-chungkhoan':'https://cafef.vn/thi-truong-chung-khoan.rss',
 'cafef-doanhnghiep':'https://cafef.vn/doanh-nghiep.rss',
 'vietstock-cophieu':'https://vietstock.vn/830/chung-khoan/co-phieu.rss',
 'vietstock-giaodichnoibo':'https://vietstock.vn/739/chung-khoan/giao-dich-noi-bo.rss',
 'vietstock-en-stocks':'https://en.vietstock.vn/52015/vietnam-stocks.rss'
};
return ids.map(id => ({ json: { source_id: id, url: urls[id] } }));

const out = {};
for (const it of $input.all()) {
  const id = it.json.source_id ?? 'unknown';
  out[id] ??= { items: 0, errors: [], first: null, fields: {} };
  const o = out[id];
  if (it.json.error) { o.errors.push(String(it.json.error.message ?? it.json.error).slice(0, 200)); continue; }
  o.items++;
  for (const k of Object.keys(it.json)) o.fields[k] = (o.fields[k] ?? 0) + 1;
  if (!o.first) {
    const iso = it.json.isoDate;
    o.first = { title: it.json.title, link: it.json.link, pubDate: it.json.pubDate, isoDate: iso,
      ict: iso ? DateTime.fromISO(iso).setZone('Asia/Ho_Chi_Minh').toISO() : null,
      contentSnippet: (it.json.contentSnippet ?? '').slice(0, 160) };
  }
}
return [{ json: { checked_at_ict: $now.setZone('Asia/Ho_Chi_Minh').toISO(), workflow_tz: $workflow.timezone ?? null, feeds: out } }];
